package com.careerpilot.modules.jobmatch.scoring;
import org.springframework.stereotype.Service;import java.util.*;
@Service public class TextSimilarityService{private static final Set<String>STOP=Set.of("a","an","and","are","as","at","be","by","for","from","in","is","it","of","on","or","our","that","the","to","we","will","with","you","your","this","have","has","job","role","work");
 public int tfIdfScore(String first,String second){List<String>a=tokens(first),b=tokens(second);if(a.isEmpty()||b.isEmpty())return 0;Set<String>vocab=new HashSet<>(a);vocab.addAll(b);double[]va=new double[vocab.size()],vb=new double[vocab.size()];int index=0;for(String term:vocab){int da=a.contains(term)?1:0,db=b.contains(term)?1:0;double idf=Math.log((3.0)/(1+da+db))+1;va[index]=frequency(a,term)/(double)a.size()*idf;vb[index]=frequency(b,term)/(double)b.size()*idf;index++;}return normalized(cosine(va,vb));}
 public double cosine(double[]a,double[]b){if(a==null||b==null||a.length==0||a.length!=b.length)return 0;double dot=0,na=0,nb=0;for(int i=0;i<a.length;i++){dot+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return na==0||nb==0?0:Math.max(-1,Math.min(1,dot/(Math.sqrt(na)*Math.sqrt(nb))));}
 public int normalizedCosine(double[]a,double[]b){return normalized(Math.max(0,cosine(a,b)));}private int normalized(double value){return (int)Math.round(Math.max(0,Math.min(1,value))*100);}private long frequency(List<String>v,String term){return v.stream().filter(term::equals).count();}private List<String>tokens(String text){if(text==null)return List.of();return Arrays.stream(text.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9+#]+"," ").trim().split("\\s+")).filter(v->v.length()>1&&!STOP.contains(v)).toList();}}
